import json,hashlib,time
from pathlib import Path
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text('utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
evidence={}
for name,prefix in [('identity','request_identity_'),('history','request_context_'),('graph','graph_verification_'),('parser','planner_input_contract_'),('relation','shared_relation_binding_'),('snapshot','snapshot_delivery_'),('gateway','gateway_verification_'),('wire','wire_compatibility_'),('derivation','execution_derivation_'),('numbers','named_number_slots_'),('style','style_scope_'),('quantities','quantity_roles_')]:
 p=sorted(R.glob(prefix+'*/RESULT.json'))[-1];d=read(p);assert d['all_passed'];evidence[name]=(p,d)
def criterion(text,name,*checks):
 p,d=evidence[name];assert checks and all(d['checks'].get(c) is True for c in checks),(text,checks)
 return {'criterion':text,'state':'passed_controlled_acceptance','evidence':str(p.relative_to(R)),'evidence_sha256':sha(p),'checks':list(checks)}
def pending(text,reason):return {'criterion':text,'state':'review_required','reason':reason}
